edits.newText:
// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Resolves a head-on collision (issue #1): the ball is currently overlapping a
// brick, so decide which face was actually hit and bounce it off that face.
//
// The axis with the SMALLER penetration is the face that was hit: the side the
// ball barely slipped past on one axis means the other axis did the crossing.
// Flip `vy` on a top/bottom hit, `vx` on a side hit, and leave the other
// component untouched. Two equal minima = a diagonal (corner) hit, where both
// components flip. Finally the ball is pushed BACK OUT of the brick, otherwise
// it would still overlap on the next frame and re-flip forever (sticky bounce).
const EPS = 1e-6;
export function deflectBall(ball, brick) {
  // Penetration depth through each of the four faces (all >= 0 while overlapping).
  const overL = ball.x + ball.r - brick.x;               // crossed the LEFT  face
  const overR = brick.x + brick.w - (ball.x - ball.r);   // crossed the RIGHT face
  const overT = ball.y + ball.r - brick.y;               // crossed the TOP    face
  const overB = brick.y + brick.h - (ball.y - ball.r);   // crossed the BOTTOM face
  const min = Math.min(overL, overR, overT, overB);

  let flipX = false;
  let flipY = false;

  if (min - overL < EPS) { ball.x = brick.x - ball.r; flipX = true; }
  if (min - overR < EPS) { ball.x = brick.x + brick.w + ball.r; flipX = true; }
  if (min - overT < EPS) { ball.y = brick.y - ball.r; flipY = true; }
  if (min - overB < EPS) { ball.y = brick.y + brick.h + ball.r; flipY = true; }

  if (flipX) ball.vx = -ball.vx;
  if (flipY) ball.vy = -ball.vy;
}

// Swept detection for the tunnelling case (issue #1): at level 6+ the ball can
// cross a whole brick in a single capped frame without ever producing a
// `collides()` overlap on either side. Detect the crossing on the SEGMENT from
// the previous to the current position, treating the brick as expanded by the
// ball radius. Returns the entry parameter t in [0,1] along the segment, or -1
// if the path clears the brick. Uses Liang-Barsky against the expanded AABB.
export function sweptHitT(ball, brick) {
  const bx = ball.px;
  const by = ball.py;
  const cx = ball.x;
  const cy = ball.y;
  if (bx === undefined || by === undefined) return -1;

  const dx = cx - bx;
  const dy = cy - by;
  if (dx === 0 && dy === 0) return -1;

  // Expanded brick: the ball centre may be this close on every side.
  const rx0 = brick.x - ball.r;
  const ry0 = brick.y - ball.r;
  const rx1 = brick.x + brick.w + ball.r;
  const ry1 = brick.y + brick.h + ball.r;

  let t0 = 0;
  let t1 = 1;
  const p = [-dx, dx, -dy, dy];
  const q = [bx - rx0, rx1 - bx, by - ry0, ry1 - by];
  for (let i = 0; i < 4; i++) {
    if (p[i] === 0) {
      if (q[i] < 0) return -1; // parallel and outside
    } else {
      const t = q[i] / p[i];
      if (p[i] < 0) {
        if (t > t1) return -1;
        if (t > t0) t0 = t;
      } else {
        if (t < t0) return -1;
        if (t < t1) t1 = t;
      }
    }
  }
  return t0 <= t1 ? t0 : -1;
}

