export function step(state, dt) {
  const { ball, paddle } = state;

  // Remember where the ball started this frame so the brick sweep in the next
  // frame() can catch high-speed tunnelling (issue #1).
  ball.px = ball.x;
  ball.py = ball.y;
  // Re-arm the per-frame brick bounce guard (bricks may share a seam):
  state._deflected = false;

  ball.x += ball.vx * dt;

