test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- Issue #1: the ball bounces off bricks instead of plowing through -----

function makeBrick(x, y) {
  return { x, y, w: BRICK_W, h: BRICK_H };
}

// Two adjacent bricks in a row, with the grid gap between them. The gap (8)
// is smaller than the ball diameter (14), so a ball straddling the seam
// overlaps BOTH bricks at once.
function seamRow() {
  const x0 = (WIDTH - 2 * (BRICK_W + BRICK_GAP)) / 2;
  return [makeBrick(x0, BRICK_TOP), makeBrick(x0 + BRICK_W + BRICK_GAP, BRICK_TOP)];
}

test('deflectBall: bottom face hit flips vy up and pushes the ball out', () => {
  const ball = { x: 300, y: BRICK_TOP + BRICK_H + 3, r: 7, vx: 40, vy: 200 };
  const brick = makeBrick(250, BRICK_TOP); // ball moving down into the top face
  deflectBall(ball, brick);
  assert.ok(ball.vy < 0, 'vy should flip to UP after hitting the top face');
  assert.equal(ball.vx, 40, 'vx must be left untouched on a vertical hit');
  assert.ok(
    ball.y <= brick.y - ball.r,
    'ball must be pushed back OUT above the brick, got y=' + ball.y,
  );
});

test('deflectBall: side face hit flips vx, never touches vy', () => {
  const brick = makeBrick(200, 100);
  const ball = { x: 200 + BRICK_W + 4, y: 110, r: 7, vx: -300, vy: -80 };
  deflectBall(ball, brick); // moving LEFT into the right face
  assert.ok(ball.vx > 0, 'vx should flip to the right');
  assert.equal(ball.vy, -80, 'vy must be left untouched on a side hit');
  assert.ok(ball.x >= brick.x + brick.w + ball.r, 'ball pushed back out to the right');
});

test('deflectBall: corner hit (equal penetration) flips both components', () => {
  // Straddle the lower-left corner of the brick: barely inside from the left
  // AND barely inside from the bottom -> the two minima tie.
  const brick = makeBrick(200, 100);
  const ball = { x: brick.x - 1, y: brick.y - 1, r: 8, vx: 100, vy: 150 };
  deflectBall(ball, brick);
  assert.ok(ball.vx < 0, 'vx should flip on the corner hit');
  assert.ok(ball.vy < 0, 'vy should flip on the corner hit');
  // Pushed out both left AND above the brick.
  assert.ok(ball.x <= brick.x - ball.r && ball.y <= brick.y - ball.r);
});

test('seam#guard: opposite bricks overlapping once per frame flip exactly once', () => {
  // Two head-on bricks sharing the seam where the ball sits. When only one
  // bounce is allowed per frame the ball must NOT double-flip (double vy=-vy
  // cancels and the ball plows through). We exercise `frame` directly with a
  // stub canvas so the real collision code runs once per pass.
  const [a, b] = seamRow();
  const state = {
    bricks: [a, b],
    combo: 0,
    score: 0,
    ball: { x: a.x + a.w + 1, y: BRICK_TOP + BRICK_H / 2, r: 7, vx: 0, vy: -200 },
  };
  frame(stubCtx(), state);
  assert.ok(state.ball.vy > 0, 'exactly one flip => vy bounced to DOWN');
  assert.equal(a.alive, false);
  assert.equal(b.alive, false);
  assert.ok(state.score > 0, 'surviving seam bricks are still scored');
});

test('tunnelling#sweep: a brick-jumping ball at high speed still bounces', () => {
