test('tunnelling#sweep: a brick-jumping ball at high speed still bounces', () => {
  // Speed 710 px/s (level 6) across a capped 50 ms frame = 35.5 px, more than
  // the 34 px it takes to cross a brick, so `collides` never fires on either
  // side. The sweep must catch it: the ball ends BELOW the brick that was
  // between the two positions.
  const brick = makeBrick(300, 100);
  const state = {
    bricks: [brick],
    combo: 0,
    score: 0,
    ball: {
      x: 307,
      y: 80,           // just above the brick (100)
      px: 307,
      py: 80,
      r: 7,
      vx: 0,
      vy: -710,        // heading UP, but the sweep goes prev -> cur (80 -> 120)
    },
  };
  // Simulate a downward leg that jumped the brick: previous position above it,
  // current position below it.
  state.ball.x = 307;
  state.ball.y = 140;
  state.ball.py = 80;
  frame(stubCtx(), state);
  assert.equal(brick.alive, false, 'the crossed brick must be destroyed');
  assert.ok(state.ball.y <= brick.y - state.ball.r, 'ball pushed back out above the brick');
});

