test('deflectBall: bottom face hit flips vy and pushes the ball out', () => {
  // Ball below the brick, closing on it (vy > 0 = moving DOWN => hits the
  // brick's BOTTOM face at y = brick.y + h). Bounce back UP, push out below.
  const ball = { x: 300, y: BRICK_TOP + BRICK_H + 3, r: 7, vx: 40, vy: 200 };
  const brick = makeBrick(250, BRICK_TOP);
  deflectBall(ball, brick);
  assert.ok(ball.vy < 0, 'vy should flip to UP after a bottom-face hit');
  assert.equal(ball.vx, 40, 'vx must be left untouched on a vertical hit');
  assert.ok(
    ball.y >= brick.y + brick.h + ball.r,
    'ball must be pushed back OUT below the brick, got y=' + ball.y,
  );
});

