    'ball must be pushed back OUT above the brick, got y=' + ball.y,
  );
});

edits.newText:
test('seam#guard: stacked bricks overlapping once per frame flip vy exactly once', () => {
  // Two bricks stacked in the same column. The ball straddles the GAP between
  // them (gap 8 < ball diameter 14), so it overlaps BOTH at once and a naive
  // `vy = -vy` on each would cancel out and let the ball straight through. The
  // per-frame guard must apply the bounce exactly once: the first brick flips
  // vy, the second (already-deflected) must not re-flip it.
  const x0 = (WIDTH - BRICK_W) / 2;
  const top = makeBrick(x0, 100);                  // spans y 100..120
  const bottom = makeBrick(x0, 100 + BRICK_H + BRICK_GAP); // y 128..148
  const gapY = 100 + BRICK_H + BRICK_GAP / 2;      // ball centre in the 8 px gap

  const state = createState(1);
  state.bricks = [top, bottom];
  state.ball = { x: x0 + BRICK_W / 2, y: gapY, r: 7, vx: 0, vy: -200 };
  frame(stubCtx(), state);
  assert.equal(top.alive, false);
  assert.equal(bottom.alive, false);
  assert.equal(
    state.ball.vy,
    200,
    'exactly one flip: vy = -200 should become +200, not stay -200 nor go to -(-(-200))',
  );
});

