  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: collision + bounce + score + drawing, all in one place.
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    // Issue #1: bricks now bounce the ball back. `_deflected` makes sure the
    // bounce is applied exactly ONCE per frame: the grid gap (8 px) is smaller
    // than the ball diameter (14 px), so a seam overlaps two bricks in the same
    // pass and a double `vy = -vy` would cancel out and let the ball straight
    // through. Subsequent overlapping bricks are still destroyed & scored, but
    // don't re-flip the velocity.
    const hit = collides(state.ball, brick);
    const sweepT = hit ? -1 : sweptHitT(state.ball, brick);

    if (!state._deflected && (hit || sweepT >= 0)) {
      if (!hit) {
        // Tunnelling: the current position is past the brick, but the segment
        // from `px/py` crossed it. Reconstruct the ball where it first touched
        // so deflectBall sees the real entry face, then bounce it back.
        const bx = state.ball.px;
        const by = state.ball.py;
        state.ball.x = bx + sweepT * (state.ball.x - bx);
        state.ball.y = by + sweepT * (state.ball.y - by);
      }
      deflectBall(state.ball, brick);
      state._deflected = true;
    }

    if (hit || sweepT >= 0) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }

    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

